import{_ as a,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const h=JSON.parse('{"title":"Vakya lunar model: inspected source and remaining correction work","description":"","frontmatter":{},"headers":[],"relativePath":"operations/vakya-lunar-source-audit-20260919.md","filePath":"operations/vakya-lunar-source-audit-20260919.md","lastUpdated":1789991296000}'),i={name:"operations/vakya-lunar-source-audit-20260919.md"};function o(d,e,s,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="vakya-lunar-model-inspected-source-and-remaining-correction-work" tabindex="-1">Vakya lunar model: inspected source and remaining correction work <a class="header-anchor" href="#vakya-lunar-model-inspected-source-and-remaining-correction-work" aria-label="Permalink to &quot;Vakya lunar model: inspected source and remaining correction work&quot;">​</a></h1><p>Maintainer research record for issue #176; not a replacement engine or a claim that present Vakya output is independently verified. Review this record when an exact replacement model and external comparison corpus are ready.</p><h2 id="primary-artifact" tabindex="-1">Primary artifact <a class="header-anchor" href="#primary-artifact" aria-label="Permalink to &quot;Primary artifact&quot;">​</a></h2><p><em>Vakyakarana with Laghuprakasika</em>, edited by T. S. Kuppanna Sastri and K. V. Sarma, 1962. <a href="https://www.ebharatisampat.in/pdfs/ebharati-pdf-1644580379VakyaKarana-LaghuParkasikaVyakhya-Ed-KuppannaSastri-SarmaKV-1962.pdf" target="_blank" rel="noreferrer">Inspected scan</a>, 339 physical PDF pages, 11,159,128 bytes; SHA-256 <code>27b4f655dc3ce19727b58df08a8be120c39c3db896eeeb3182fe6ecab57b3eab</code>. Retrieved 2026-09-19. Relevant English pages were rendered and visually checked; OCR was used for navigation, not as sole authority for numeric transcription.</p><h2 id="what-the-edition-establishes" tabindex="-1">What the edition establishes <a class="header-anchor" href="#what-the-edition-establishes" aria-label="Permalink to &quot;What the edition establishes&quot;">​</a></h2><p>Printed pages 253–254 (physical PDF pages 290–291), chapter I verses 9–14a, describe successive reductions of Kali days after subtracting 1,600,984: divide by 12,372, then the remainder by 3,031, then the remainder by 248. The final remainder selects a lunar mnemonic, with quotient-dependent angular terms and a daily-motion correction. Appendix II, printed pages 125–134, contains the lunar table identified by the translation&#39;s footnote 7.</p><p>Thus <strong>3,031 is a sourced step</strong>, but this does not establish the repository&#39;s nine-value offset. The source does not describe adding one of nine half-degree offsets to the Surya Siddhanta Moon for successive 3,031-day blocks.</p><p>The worked example on printed page 254 uses Kali day 1,844,004. Its reductions yield quotients 19, 2 and 7, and remainder 154. The tabular longitude for entry 154 is 7 signs 21 degrees 48 minutes; entry 153 is 7 signs 7 degrees 36 minutes. The example&#39;s final Moon longitude is 4 signs 11 degrees 17 minutes 32 seconds. The two rows were also visually cross-checked in Appendix II, printed page 130 (physical PDF page 167). <code>tests/fixtures/vakya_1962_worked_example.json</code> and <code>tests/test_vakya_source_example.py</code> reproduce the printed reductions, angular sums, daily-motion correction and local correction with rational arithmetic. This is an independently printed arithmetic example, not a modern city/date Panchangam comparison.</p><p>Printed pages 255–256 (physical PDF pages 292–293), verses 14b–17a and example 4, then reduce to local true sunrise using daylight, longitude relative to Ujjain, and the specified equation-of-time component. The Pudukkottai example gives 4 signs 11 degrees 9 minutes 21 seconds after that reduction. Substituting a modern sunrise helper without deciding this historical time model would not be a source-faithful reconstruction.</p><h2 id="gap-register-and-bounded-next-work" tabindex="-1">Gap register and bounded next work <a class="header-anchor" href="#gap-register-and-bounded-next-work" aria-label="Permalink to &quot;Gap register and bounded next work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim or requirement</th><th>Evidence now</th><th>Remaining work</th></tr></thead><tbody><tr><td>3,031-day quantity</td><td>Located exactly in I.9–11</td><td>Retain as one reduction, not an entire nine-phase model</td></tr><tr><td>248-day lunar table</td><td>Complete 248-row numeric transcription with page/row locators</td><td>Independent second transcription, unresolved 100/148 discrepancy and wrap/zero-remainder indexing</td></tr><tr><td>Angular constants and correction</td><td>Located in I.9–14a and worked example 3</td><td>Printed example reproduced; single-transcriber full table published, general boundary cases still required</td></tr><tr><td>Epoch, meridian and local sunrise</td><td>Kali-day and Ujjain/local reduction described in I.2–3 and I.14b–17a</td><td>Specify fractional-day and modern coordinate conversion explicitly</td></tr><tr><td>Modern published Vakya output</td><td>No independently inspected exact city/date corpus in this audit</td><td>Inspect published scans and establish their regional/table/time convention before comparison</td></tr><tr><td>Current engine</td><td>Nine offsets over 3,031-day blocks, regression-pinned</td><td>Replace only after model/corpus review and explicit frozen-core approval</td></tr></tbody></table><p>The correction should be a separate, versioned release with unchanged unrelated engine, feed and workflow behavior. Keep #176 open and the current public evidence state <code>engine_pinned</code> / <code>project_heuristic</code>; finding a primary source does not retroactively validate the implementation. No frozen source was edited.</p><h2 id="current-published-output-leads" tabindex="-1">Current published-output leads <a class="header-anchor" href="#current-published-output-leads" aria-label="Permalink to &quot;Current published-output leads&quot;">​</a></h2><p>The <a href="https://srirangaminfo.com/vakya-panchangam-srirangam.php" target="_blank" rel="noreferrer">Srirangam 2026–2027 scan collection</a> and <a href="https://nkmysamithi.org/download_panchangam.php" target="_blank" rel="noreferrer">NKMY Samithi publisher downloads</a> were located on 2026-09-19. These are leads, not fixture evidence: a search listing or cover does not establish the exact daily values, city meridian, time units, or correspondence to this edition&#39;s method. Do not use a Drik or Surya Siddhanta almanac as a mislabeled Vakya lunar oracle.</p><h2 id="complete-numeric-transcription-—-2026-09-21" tabindex="-1">Complete numeric transcription — 2026-09-21 <a class="header-anchor" href="#complete-numeric-transcription-—-2026-09-21" aria-label="Permalink to &quot;Complete numeric transcription — 2026-09-21&quot;">​</a></h2><p>The <a href="./../research/vakya-1962-lunar-table/README">research transcription</a> records all 248 Appendix II numeric rows, with CSV/JSON parity and physical/printed page locators. It is single-transcriber evidence, with a separate spot review of days 100 and 148; it is not full independent double-entry certification. Both minute cells read 17. Their sum modulo a circle is 0 signs 27 degrees 34 minutes, ten arcminutes below the printed 27 degrees 44 minutes check. Neither cell is silently corrected. The source-authority discrepancy remains open, as do epoch, interpolation and modern comparison decisions. These data are research evidence only and are not consumed by any calculation engine.</p>',16)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
